theory:
**Паттерн переиспользования буфера (Zero-Allocation Buffer Reuse):**
- Срез `s[:0]` сбрасывает длину `Len = 0`, но сохраняет исходную емкость `Cap` и указатель на память `Data`;
- Последующие вызовы `append` пишут в уже выделенный массив без единой аллокации в куче;
- Является ключевым паттерном для `sync.Pool` и высоконагруженных сетевых сервисов.

**Правило минимальной длины в `copy(dst, src)`:**
- Число скопированных элементов всегда строго равно $\min(	ext{len}(dst), 	ext{len}(src))$;
- Если `dst` короче `src`, копируются только первые `len(dst)` элементов;
- Остальные элементы `src` игнорируются без генерации паники.

code_blocks.code:
package main

import "fmt"

func main() {
	src := []int{10, 20, 30, 40, 50}
	dst := make([]int, 2) // Целевой срез короче исходного!

	copied := copy(dst, src)

	fmt.Printf("src:         %v (len=%d)\n", src, len(src))
	fmt.Printf("dst:         %v (len=%d)\n", dst, len(dst))
	fmt.Printf("Скопировано: %d элементов (min(len(dst), len(src)))\n", copied)
}

theory:
**Строгое разграничение `len` и `cap` при индексации:**
- Индексация `s[i]` проверяет условие $0 \le i < 	ext{len}(s)$;
- Даже если `cap(s) == 5`, ячейка `s[4]` не входит в диапазон длины `len(s) == 3`;
- Прямая запись `s[4] = 10` вызывает панику `index out of range [4] with length 3`.

code_blocks.code:
package main

import "fmt"

func main() {
	s := make([]int, 3, 5)
	fmt.Printf("Структура среза: %#v | len = %d, cap = %d\n\n", s, len(s), cap(s))

	defer func() {
		if r := recover(); r != nil {
			fmt.Printf("⚠️ Перехвачена паника: %v\n", r)
			fmt.Println("Причина: запись s[4] запрещена, так как 4 >= len(s)!")
		}
	}()

	fmt.Println("Попытка прямой записи s[4] = 10...")
	s[4] = 10 // Паника!
}

package main

import "fmt"

func ReverseInPlace(s []int) {
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		s[i], s[j] = s[j], s[i]
	}
}

func main() {
	numbers := []int{10, 20, 30, 40, 50, 60}

	fmt.Printf("До разворота:    %v\n", numbers)
	ReverseInPlace(numbers)
	fmt.Printf("После разворота: %v\n", numbers)
}

theory:
Детальный анализ поведения в веб-сервисах:
- Для Go-кода `var s1 []int` и `s2 := []int{}` взаимозаменяемы при вызове `len`, `cap` и `append`;
- Для внешних REST/JSON API: `nil` превращается в `null`, а пустой срез — в `[]`.

code_blocks.code:
package main

import (
	"encoding/json"
	"fmt"
)

type CartResponse struct {
	User  string   `json:"user"`
	Items []string `json:"items"`
}

func main() {
	var nilItems []string        // nil срез
	emptyItems := []string{}     // пустой срез

	// 1. Поведение в Go:
	fmt.Printf("nilItems:   len = %d, cap = %d, isNil = %t\n", len(nilItems), cap(nilItems), nilItems == nil)
	fmt.Printf("emptyItems: len = %d, cap = %d, isNil = %t\n\n", len(emptyItems), cap(emptyItems), emptyItems == nil)

	// 2. Сериализация в JSON:
	res1, _ := json.Marshal(CartResponse{User: "Alice", Items: nilItems})
	res2, _ := json.Marshal(CartResponse{User: "Bob", Items: emptyItems})

	fmt.Printf("JSON (nilItems):   %s\n", res1)
	fmt.Printf("JSON (emptyItems): %s\n", res2)
}

go run main.go
# nilItems:   len = 0, cap = 0, isNil = true
# emptyItems: len = 0, cap = 0, isNil = false
# 
# JSON (nilItems):   {"user":"Alice","items":null}
# JSON (emptyItems): {"user":"Bob","items":[]}

theory:
**Копирование элементов в `for range`:**
- `for _, p := range persons` на каждой итерации копирует всю структуру `Person` в локальную переменную `p`;
- Мутация `p.Age++` изменяет только эту локальную копию;
- Для изменения данных в срезе обращаются по индексу: `persons[i].Age++`.

code_blocks.code:
package main

import "fmt"

type Person struct {
	Name string
	Age  int
}

func main() {
	team := []Person{
		{Name: "Иван", Age: 25},
		{Name: "Елена", Age: 30},
	}
	fmt.Printf("1. Исходный срез:   %+v\n", team)

	// ОШИБКА: p - это локальная копия
	for _, p := range team {
		p.Age = 99
	}
	fmt.Printf("2. После _, p :=:   %+v (НЕ изменился!)\n", team)

	// ПРАВИЛЬНО: через прямой индекс
	for i := range team {
		team[i].Age = 99
	}
	fmt.Printf("3. После team[i]:   %+v (УСПЕШНО!)\n", team)
}

theory:
**Механика удаления элементов:**
- `append(s[:i], s[i+1:]...)` производит сдвиг элементов на месте;
- Базовый массив остается прежним, адрес `&s[0]` не меняется;
- Емкость `cap` сохраняется.

code_blocks.code:
package main

import "fmt"

func DeleteByIndex(s []int, i int) []int {
	return append(s[:i], s[i+1:]...)
}

func main() {
	numbers := []int{10, 20, 30, 40, 50}
	addrBefore := fmt.Sprintf("%p", &numbers[0])

	fmt.Printf("До удаления:    %v (адрес: %s, cap: %d)\n", numbers, addrBefore, cap(numbers))

	numbers = DeleteByIndex(numbers, 2) // Удаляем 30
	addrAfter := fmt.Sprintf("%p", &numbers[0])

	fmt.Printf("После удаления: %v (адрес: %s, cap: %d - ТОТ ЖЕ!)\n", numbers, addrAfter, cap(numbers))
}

package main

import "fmt"

func main() {
	s := []int{1, 2, 3, 4, 5}
	s2 := s[2:4] // s2 указывает на [3, 4]

	fmt.Printf("Исходный s:  %v\n", s)
	fmt.Printf("Подсрез s2:  %v\n\n", s2)

	// Меняем первый элемент подсреза:
	s2[0] = 99

	fmt.Println("После s2[0] = 99:")
	fmt.Printf("Подсрез s2:  %v\n", s2)
	fmt.Printf("Исходный s:  %v (элемент s[2] изменился на 99!)\n", s)
}

package main

import "fmt"

func RemoveOrdered(s []string, i int) []string {
	if i < 0 || i >= len(s) {
		return s
	}
	return append(s[:i], s[i+1:]...)
}

func main() {
	tasks := []string{"Auth", "Database", "BugFix", "Deploy", "Logs"}
	fmt.Printf("До:    %v\n", tasks)

	tasks = RemoveOrdered(tasks, 2) // Удаляем "BugFix"
	fmt.Printf("После: %v\n", tasks)
}

theory:
**Наблюдение за сменой адреса базового массива:**
- При `append`, пока `len <= cap`, адрес `&s[0]` остается неизменным;
- В момент, когда `len` превышает `cap`, выделяется новый массив в куче, и адрес `&s[0]` скачкообразно меняется;
- Старый массив помечается как мусор для сборщика.

code_blocks.code:
package main

import "fmt"

func main() {
	s := make([]int, 0, 2)
	var prevAddr uintptr

	for i := 1; i <= 10; i++ {
		s = append(s, i)
		currAddr := uintptr(fmt.Sprintf("%p", &s[0])[2:]) // адрес первого элемента
		_ = currAddr

		reallocMark := ""
		if i == 1 || cap(s) != len(s)-1 {
			// Отслеживаем смену адреса
		}
		fmt.Printf("Итерация #%2d -> Адрес &s[0]: %p | len: %2d | cap: %2d %s\n",
			i, &s[0], len(s), cap(s), reallocMark)
	}
}

theory:
**Анатомия передачи дескриптора среза:**
- При вызове `func f(s []int)` в функцию передается **локальная копия структуры `SliceHeader`**;
- `append` внутри функции обновляет поле `Len` в этой локальной копии;
- Поле `Len` исходного среза в вызывающей функции остается неизменным;
- **Идиома Go:** Функции, модифицирующие длину среза, обязаны возвращать новый срез: `func f(s []int) []int`.

code_blocks.code:
package main

import "fmt"

// Неправильно: срез передается по значению, len в main не изменится
func BadAppend(s []int) {
	s = append(s, 999)
}

// Правильно: идиоматичный возврат обновленного среза
func GoodAppend(s []int) []int {
	return append(s, 999)
}

func main() {
	s := []int{1, 2, 3}

	fmt.Printf("1. До вызовов:     %v (len=%d)\n", s, len(s))
	BadAppend(s)
	fmt.Printf("2. После BadAppend: %v (len=%d - ДЛИНА НЕ ИЗМЕНИЛАСЬ!)\n", s, len(s))

	s = GoodAppend(s)
	fmt.Printf("3. После GoodAppend:%v (len=%d - УСПЕШНО!)\n", s, len(s))
}

